class StockUpDownAction extends SeqEventActionHandler {
    //ストック数は0よりは減らない。
    // このActionによりストック数は0になるが、今使っているボールがある限りは
    // ゲームオーバーにならない。
    #value = 0;
    /** 
     * @param {Number} value 
     * @param {EventActionHandler} nextAction */
    constructor(value, nextAction) {
        super(nextAction);
        this.#value = value;
    }
    invoke() {
        game.stock = Math.max(game.stock + this.#value, 0);
    }
}

